#!/usr/bin/env python3
"""One-time migration payload for the Stoned Lack 570 version-2 package."""

from __future__ import annotations

import base64
import hashlib
import io
import zipfile
from pathlib import Path

PAYLOAD = (
    "" 
    "" 
    "" 
    "AAgA2bHqXFX7MApWOwAAdy4BAAoAAAAAAAAAAAAAAIAB80YAAHRha2VzLmpzb25QSwECFAMUAAAACADZsepcDAwyrkMXAABmoAEADQAAAAAAAAAAAAAAgAFxggAAbWVudGlvbnMuanNvblBLAQIUAxQAAAAIANmx6lypraGe7AMAAEsIAAAKAAAAAAAAAAAAAACAAd+ZAABpbmRleC5qc29uUEsFBgAAAAAEAAQA4wAAAPOdAAAAAA=="
)

EXPECTED_ZIP_SHA256 = "9863a5fe41a96810f929bd9a0e1e5ecd4221cc6561ce91807af7aa2d51021d75"
TARGET = Path("fantasy-management/sources/podcasts/stoned-lack/episodes/2026/sl_0570")
EXPECTED_FILES = {"episode.md", "takes.json", "mentions.json", "index.json"}


def main() -> None:
    archive = base64.b64decode(PAYLOAD)
    actual_hash = hashlib.sha256(archive).hexdigest()
    if actual_hash != EXPECTED_ZIP_SHA256:
        raise RuntimeError(f"Migration payload hash mismatch: {actual_hash}")

    TARGET.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(archive)) as source:
        names = set(source.namelist())
        if names != EXPECTED_FILES:
            raise RuntimeError(f"Unexpected archive contents: {sorted(names)}")
        for name in sorted(names):
            data = source.read(name)
            (TARGET / name).write_bytes(data)
            print(f"wrote {TARGET / name} ({len(data)} bytes)")


if __name__ == "__main__":
    main()
